    p.del_flag = '0'
     AND p.policy_no LIKE CONCAT('%', #{policyNo}, '%')
     AND p.policy_name LIKE CONCAT('%', #{policyName}, '%')
     AND p.customer_id = #{customerId}
     AND p.basis = #{basis}
     AND p.period_type = #{periodType}
