UPDATE mk_rebate_policy
policy_name = #{policyName}, customer_id = #{customerId}, basis = #{basis}, period_type = #{periodType}, tier_min = #{tierMin}, tier_max = #{tierMax}, rebate_rate = #{rebateRate}, start_date = #{startDate}, end_date = #{endDate}, status = #{status}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark},
WHERE policy_id = #{policyId}

UPDATE mk_rebate_settle
status = #{status}, redeem_type = #{redeemType}, redeem_date = #{redeemDate}, redeem_by = #{redeemBy}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark},
WHERE settle_id = #{settleId}

mapper.select:
SELECT IFNULL(SUM(o.order_amount), 0)
FROM mk_order o
WHERE o.del_flag = '0' AND o.customer_id = #{customerId}
  AND o.order_status IN ('2', '3', '4')
  AND o.create_time >= #{beginTime} AND o.create_time < #{endTime}

SELECT s.settle_id, s.settle_no, s.customer_id, s.customer_name, s.period, s.policy_no, s.policy_name,
       s.achieve_amount, s.rebate_rate, s.rebate_amount, s.status, s.redeem_type, s.redeem_date, s.redeem_by,
       s.del_flag, s.create_by, s.create_time, s.update_by, s.update_time, s.remark
FROM mk_rebate_settle s

    s.del_flag = '0'
     AND s.settle_no LIKE CONCAT('%', #{settleNo}, '%')
     AND s.customer_id = #{customerId}
     AND s.period = #{period}
     AND s.policy_no = #{policyNo}
     AND s.status = #{status}

ORDER BY s.settle_id DESC
